import { defineConfig } from "vitest/config";

// Unit tests of every package (`npm run test`). Each package has its own
// vitest.config.ts (environment, aliases); coverage is configured only here,
// because Vitest measures it for all projects together.
export default defineConfig({
  test: {
    projects: ["packages/*"],
    coverage: {
      provider: "v8",
      include: ["packages/*/src/**/*.{ts,tsx}"],
      exclude: [
        "**/*.test.{ts,tsx}",
        // Generated by the MikroORM CLI (`db:migration:create`); executed by
        // `npm run db:migrate` in the integration tests, not unit-testable.
        "packages/db/src/migrations/**",
      ],
      // AGENTS.md: every feature ships with 100% unit-test coverage.
      thresholds: { lines: 100, branches: 100, functions: 100, statements: 100 },
      reporter: ["text-summary", "text", "html", "json-summary"],
    },
  },
});
